  "contradictory_card_ids": ["C75"],
  "prediction_basis_card_ids": ["C19", "C01", "C02", "C04", "C05", "C12", "C14", "C24", "C74"],
  "claims": [
    {
      "claim": "The query is a staurosporine-type indolocarbazole glycoside/lactam; the closest supplied structural analog LCS1269 has a predicted human intestinal absorption-based bioavailability >30% (F30% 0.213), supporting F ≥ 20%.",
      "card_ids": ["C19"]
    },
    {
      "claim": "Vinorelbine, a large lipophilic alkaloid, has measured absolute oral bioavailability of 43 ± 14% for the soft-gel capsule in fasted patients (close to 40% by AUCinf), 36–43% with food, and 25–27% for a liquid-filled capsule, all above the 20% threshold.",
      "card_ids": ["C02", "C04", "C05", "C12", "C14", "C24"]
    },
    {
      "claim": "Ondansetron, a carbazole-containing drug, has absolute oral bioavailability of 50–65% in fasted volunteers and remains at 40% after rifampin pretreatment, supporting that this scaffold can achieve F ≥ 20%.",
      "card_ids": ["C01", "C03"]
    },
    {
      "claim": "The closest L6 analog UCN-01 has observed human clearance <1% of hepatic blood flow, indicating negligible hepatic first-pass loss, while its in vitro hepatocyte turnover was moderate-high; this in-vivo-weighted evidence does not support F < 20% for the query.",
      "card_ids": ["C74", "C75"]
    },
    {
      "claim": "L6 hepatic-clearance records for paclitaxel, S002-333, amrubicin, paeoniflorin, and other unrelated compounds do not provide query-specific or close-analog evidence of high first-pass loss.",
      "card_ids": ["C66", "C67", "C68", "C69", "C70", "C71", "C72", "C73", "C76", "C77"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C66", "C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability data are available for the query molecule itself.",
    "No query-specific hepatic clearance or metabolic stability data are available; L6 records are for UCN-01 and structurally unrelated compounds.",
    "UCN-01 shows conflicting in vitro high turnover versus in vivo low observed clearance, and transferability to the N-benzoylstaurosporine query is uncertain.",
    "The LCS1269 record is a predicted HIA-based value rather than a measured absolute bioavailability.",
    "Vinorelbine bioavailability is formulation-dependent, and the query formulation is unspecified.",
    "Query P-gp/CYP3A4 substrate status and first-pass metabolism are not established by any supplied record."
  ],
  "decision_summary": "L6 hepatic-clearance/metabolic-stability records are mostly for unrelated compounds; the closest analog UCN-01 shows low observed human clearance (<1% QH) despite moderate-high in vitro hepatocyte turnover, which does not provide affirmative evidence for F < 20% and is broadly consistent with the high prediction. The high prediction is retained with moderate confidence."
}

